        public static readonly string[] Sources={
            "# Research Loops first, or enable unrestricted syntax in Settings.\nwhile True:\n    harvest()",
            "while True:\n    for row in range(get_world_size()):\n        for col in range(get_world_size()):\n            if can_harvest():\n                harvest()\n            if get_entity_type() == None:\n                plant(Entities.Grass)\n            move(East)\n        move(North)",
            "while True:\n    for row in range(get_world_size()):\n        for col in range(get_world_size()):\n            if can_harvest():\n                harvest()\n            if get_entity_type() == None:\n                if (get_pos_x()+get_pos_y())%2 == 0:\n                    plant(Entities.Tree)\n                else:\n                    plant(Entities.Bush)\n            move(East)\n        move(North)",
            "# Clear grass first. Keep carrot seeds in inventory.\nwhile True:\n    all_ready = True\n    for row in range(get_world_size()):\n        for col in range(get_world_size()):\n            if get_ground_type() != Grounds.Soil:\n                till()\n            if get_entity_type() == None or get_entity_type() == Entities.Dead_Pumpkin:\n                plant(Entities.Pumpkin)\n            if get_entity_type() != Entities.Pumpkin or not can_harvest():\n                all_ready = False\n            move(East)\n        move(North)\n    if all_ready:\n        harvest()",
            "# Run on a field of mature cacti. Bubble each row, then each column.\nfor axis in [East, North]:\n    for sweep in range(get_world_size()):\n        for row in range(get_world_size()):\n            for col in range(get_world_size()-1):\n                if measure() > measure(axis):\n                    swap(axis)\n                move(axis)\n            move(axis)\n            if axis == East:\n                move(North)\n            else:\n                move(East)\nharvest()",
            "# Generate a maze from a bush first. Explore using a stack.\ndirections = [North, East, South, West]\ndef reverse(direction):\n    return directions[(directions.index(direction)+2)%4]\nvisited = set()\npath = []\nwhile get_entity_type() != Entities.Treasure:\n    visited.add((get_pos_x(),get_pos_y()))\n    advanced = False\n    for direction in directions:\n        if can_move(direction):\n            move(direction)\n            position = (get_pos_x(),get_pos_y())\n            if position not in visited:\n                path.append(direction)\n                advanced = True\n                break\n            move(reverse(direction))\n    if not advanced:\n        if len(path) == 0:\n            break\n        move(reverse(path.pop()))\nif get_entity_type() == Entities.Treasure:\n    harvest()",
            "def column():\n    for row in range(get_world_size()):\n        if can_harvest():\n            harvest()\n        move(North)\n    return True\nworkers=[]\nfor col in range(get_world_size()):\n    handle=spawn_drone(column)\n    if handle == None:\n        column()\n    else:\n        workers.append(handle)\n    move(East)\nfor worker in workers:\n    wait_for(worker)",
            "# A minimal grass-funded research controller.\ndef afford(cost):\n    if cost == None:\n        return False\n    for item in cost:\n        if num_items(item) < cost[item]:\n            return False\n    return True\nwhile num_unlocked(Unlocks.Speed) < 3:\n    if can_harvest():\n        harvest()\n    if afford(get_cost(Unlocks.Speed)):\n        unlock(Unlocks.Speed)",
            "# Use an even-sized empty field and keep cactus in inventory.\nchange_hat(Hats.Dinosaur_Hat)\nwhile True:\n    direction=East\n    if get_pos_x()==0:\n        if get_pos_y()>0:\n            direction=South\n    elif get_pos_y()%2==0:\n        if get_pos_x()==get_world_size()-1:\n            direction=North\n    else:\n        direction=West\n        if get_pos_x()==1 and get_pos_y()!=get_world_size()-1:\n            direction=North\n    if not move(direction):\n        break\nchange_hat(Hats.Straw_Hat)"
        };
        public static readonly string[] Requirements={"Loops / 循环","Loops + Senses / 循环与传感器","Trees + Planting / 林木与种植","Pumpkins + carrot supply / 南瓜与胡萝卜库存","Cactus + a mature field / 仙人掌成熟田地","Maze + Functions + Sets / 迷宫、函数与集合","Megafarm + Functions + Lists / 并行无人机、函数与列表","Automatic research + Costs / 自动科研与成本查询","Dinosaurs + even field / 长尾探索与偶数边长田地"};
        public const string Guide="harvest() / can_harvest()\nplant(Entities.Grass) / plant(Entities.Bush) / plant(Entities.Tree)\nplant(Entities.Carrot) / plant(Entities.Pumpkin)\nplant(Entities.Sunflower) / plant(Entities.Cactus)\nmove(North / East / South / West) -> True / False\ncan_move(direction) -> True / False\ntill() / use_item(Items.Water) / use_item(Items.Fertilizer)\nget_pos_x() / get_pos_y() / get_world_size()\nget_entity_type() / get_ground_type() / get_water()\nnum_items(Items.Hay) / num_unlocked(Unlocks.Speed)\nget_cost(Unlocks.Speed) / unlock(Unlocks.Speed)\nget_companion() -> (entity, (x, y)) or None\nmeasure() / measure(direction) / swap(direction)\nspawn_drone(function, args...) -> handle or None\nwait_for(handle) -> return value / has_finished(handle)\nnum_drones() / max_drones()\nget_time() / get_tick_count() / random()\nsimulate(file, unlocks, items, globals, seed, speedup)\nchange_hat(Hats.Straw_Hat) / change_hat(Hats.Dinosaur_Hat)\nset_world_size(size) / set_execution_speed(speed)\nclear() / do_a_flip()\nprint(values...) / quick_print(values...)\n\nNamespaces: Entities, Items, Grounds, Unlocks, Hats, Leaderboards.\nPrograms: import helpers / from helpers import tend.\nCollections: [1,2], (1,2), {1,2}, {'seed': 4}.\nData: values[0], costs['hay'], values.append(3), visited.add((x,y)).\nFunctions: def work(x, count=1): ... return result.\n\nA task has independent memory. Return values are collected by wait_for().\nA blocked maze move returns False. Normal field edges wrap; tail mode does not.\nSimulation creates a new isolated farm. It cannot modify the live inventory.";
        public const string GuideZH="用代码照料农田，收获物资并解锁新的规则。新开局请先运行 harvest()，等草成熟后再运行，积累干草。研究循环后可载入第一份循环模板。\n\n【生产】\nharvest() 收获；can_harvest() 是否成熟\nplant(Entities.Grass / Bush / Tree / Carrot / Pumpkin / Sunflower / Cactus)\ntill() 切换草地与耕地\nuse_item(Items.Water) 浇水；use_item(Items.Fertilizer) 催熟并感染；合并收获按感染作物比例产出奇异物质\nuse_item(Items.Weird_Substance) 翻转本格和邻格感染\n\n【观察】\nget_pos_x() / get_pos_y() / get_world_size()\nget_entity_type() / get_ground_type() / get_water()\nnum_items(Items.Hay) 查询库存\nget_companion() 研究伴生种植后返回类型和目标坐标\nmeasure() 测量花瓣、仙人掌尺寸或目标位置\nswap(direction) 交换相邻仙人掌\n\n【移动】\nmove(North / East / South / West) 返回是否成功\ncan_move(direction) 预判墙壁及尾巴\n普通田地越界环绕，迷宫和长尾模式不能环绕。\n\n【研究】\nget_cost(Unlocks.Speed) 查询资源成本\nnum_unlocked(Unlocks.Speed) 查询研究等级\nunlock(Unlocks.Speed) 支付物资完成研究\n\n【并行】\nspawn_drone(function, 参数...) 返回任务句柄或 None\nwait_for(handle) 等待任务并取得返回值\nhas_finished(handle) 检查任务是否结束\nnum_drones() / max_drones()\n每台机器具有独立变量与集合副本，农场与库存共享。机器可以位于同一格，不发生实体碰撞。\n\n【实验】\nsimulate(程序名, 科技, 库存, 全局变量, 随机种子, 加速)\n模拟不会改变真实农场库存或作物，结束返回耗时。\nleaderboard_run(Leaderboards.Hay, 程序名, 加速)\n竞速使用独立 8×8 中阶农场，目标按资源区分，在竞速列表查看；达标后程序须自行结束。\nget_time() / get_tick_count() 查询时间与指令计数\nset_world_size(size) / set_execution_speed(speed) 用于调试\n\n【语言与调试】\n支持带参函数、默认参数、返回值、闭包、模块导入、列表、元组、集合和字典。\nimport helpers / from helpers import tend\nvalues.append(3) / visited.add((x,y)) / costs['hay']\n暂停后可单步；F9 为当前光标行切换断点，也可在设置中输入行号。\nCmd/Ctrl+Z 撤销，Cmd/Ctrl+Shift+Z 重做。\nprint(...) / quick_print(...) 输出值。\n程序执行受步骤、集合大小与递归深度限制，无操作系统访问能力。\n\n【文件】\n设置中启用外部编辑器可导出 .py 和接口提示文件，再监视保存的修改。\n多个程序可以分别打开为可拖动的编辑窗口。主工作台运行会重启控制程序，浮动窗口可在数量允许时独立启动另一个程序。";
