        public const string Stubs="# Interface hints for Verdant Circuit 0.11.1. This is not a full Python runtime.\nfrom typing import Any, Callable\ndef harvest() -> bool: ...\ndef can_harvest() -> bool: ...\ndef move(direction: Any) -> bool: ...\ndef can_move(direction: Any) -> bool: ...\ndef plant(entity: Any) -> bool: ...\ndef till() -> None: ...\ndef use_item(item: Any, n: int = 1) -> bool: ...\ndef measure(direction: Any = None) -> Any: ...\ndef swap(direction: Any) -> bool: ...\ndef get_pos_x() -> int: ...\ndef get_pos_y() -> int: ...\ndef get_world_size() -> int: ...\ndef get_entity_type() -> Any: ...\ndef get_ground_type() -> Any: ...\ndef get_water() -> float: ...\ndef get_companion() -> Any: ...\ndef num_items(item: Any) -> float: ...\ndef get_cost(item: Any, level: int = -1) -> dict: ...\ndef num_unlocked(item: Any) -> int: ...\ndef unlock(item: Any) -> bool: ...\ndef spawn_drone(function: Callable, *args: Any) -> Any: ...\ndef wait_for(handle: Any) -> Any: ...\ndef has_finished(handle: Any) -> bool: ...\ndef num_drones() -> int: ...\ndef max_drones() -> int: ...\ndef get_time() -> float: ...\ndef get_tick_count() -> int: ...\ndef random() -> float: ...\ndef print(*values: Any) -> None: ...\ndef quick_print(*values: Any) -> None: ...\n";
